      "Структура одного хода: частичное выявление потребности (вопрос) → ответ клиента → комплимент или социальное доказательство → кусочек презентации, закрывающий именно эту потребность → промежуточное закрытие или новый вопрос.",
      "Каждое сообщение заканчивайте вопросом. Сообщение без вопроса — потерянный ход: диалог повисает, инициатива уходит клиенту.",
      "Сколько «розыгрышей» нужно? Столько, сколько потребуется — иногда десятки. Вы разматываете клубок потребностей и постепенно доносите ценность, как в шахматах, а не в шашках."
